-- Original native sleep-food membership and period; wake timing is documented Wakemu policy.
CREATE TABLE native_pet_hibernation_food_policy (
    model_id integer NOT NULL REFERENCES native_pet_models(model_id),
    item_ref integer NOT NULL CHECK(item_ref>0),
    duration_ms bigint NOT NULL CHECK(duration_ms>0),
    source_sha256 text NOT NULL CHECK(length(source_sha256)=64),
    PRIMARY KEY(model_id,item_ref)
);
CREATE INDEX inventory_pets_hibernation_due ON inventory_pets(sleep_date) WHERE sleep_item_ref>0 AND sleep_date>0;
CREATE TABLE pet_hibernation_receipts (
    account_id bigint NOT NULL REFERENCES accounts(id),
    character_id bigint NOT NULL REFERENCES characters(id),
    pet_uid bigint NOT NULL,
    food_uid bigint NOT NULL,
    request_sha256 bytea NOT NULL,
    after_revision bigint NOT NULL CHECK(after_revision>0),
    applied_at_ms bigint NOT NULL CHECK(applied_at_ms>0),
    wakes_at_ms bigint NOT NULL CHECK(wakes_at_ms>applied_at_ms),
    PRIMARY KEY(pet_uid,after_revision)
);
